import { Page, Frame, expect } from '@playwright/test';
import { createCollection, openNewRequestPanel, createRequest, openRequest, runCommand } from '../../utils/page/actions';
import { buildCommonLocators } from '../../utils/page/locators';
import { selectDropdownItem } from '../../utils/page/oauth2-actions';

export type GrantType = 'Client Credentials' | 'Password Credentials' | 'Authorization Code' | 'Implicit';

export async function setupOAuth2Request(
  page: Page,
  sidebar: Frame,
  tmpDir: string,
  collectionName: string,
  grantType: GrantType,
  url: string
): Promise<Frame> {
  await createCollection(page, sidebar, collectionName, tmpDir);
  const newReqPanel = await openNewRequestPanel(page, sidebar, collectionName);
  await createRequest(page, newReqPanel, sidebar, collectionName, 'User Info', url);
  const editor = await openRequest(page, sidebar, collectionName, 'User Info');

  const oauth2 = buildCommonLocators(editor).oauth2;
  await buildCommonLocators(editor).tabs.byText('Auth').click();
  await selectDropdownItem(editor, oauth2.authModeSelector(), 'OAuth 2.0');
  await selectDropdownItem(editor, oauth2.grantTypeSelector(), grantType);
  await expect(oauth2.getTokenBtn()).toBeVisible();

  return editor;
}

function fieldRowByLabel(editor: Frame, label: string) {
  return editor.locator('label').filter({ hasText: label }).first().locator('..');
}

export async function fillField(page: Page, editor: Frame, keyOrLabel: string, value: string): Promise<void> {
  let row = buildCommonLocators(editor).oauth2.field(keyOrLabel);
  if (await row.count() === 0) {
    row = fieldRowByLabel(editor, keyOrLabel);
  }

  const cm = row.locator('.CodeMirror');
  await expect(cm).toBeVisible();
  await cm.click();
  const modifier = process.platform === 'darwin' ? 'Meta' : 'Control';
  await page.keyboard.press(`${modifier}+a`);
  await page.keyboard.press('Backspace');
  await page.keyboard.insertText(value);
  await page.keyboard.press('Tab');
}

export async function selectCredentialsPlacement(
  editor: Frame,
  placement: 'Request Body' | 'Basic Auth Header'
): Promise<void> {
  const trigger = fieldRowByLabel(editor, 'Add Credentials to').locator('.token-placement-selector');
  await selectDropdownItem(editor, trigger, placement);
}

export async function enablePkce(editor: Frame): Promise<void> {
  const checkbox = fieldRowByLabel(editor, 'Use PKCE').locator('input[type="checkbox"]');
  await checkbox.check();
  await expect(checkbox).toBeChecked();
}

export async function clickGetAccessToken(editor: Frame): Promise<void> {
  const getTokenBtn = buildCommonLocators(editor).oauth2.getTokenBtn();
  await expect(getTokenBtn).toBeEnabled();
  await getTokenBtn.click();
}

export async function expectAccessToken(editor: Frame): Promise<void> {
  const oauth2 = buildCommonLocators(editor).oauth2;
  await expect(oauth2.tokenTitle().filter({ hasText: 'Access Token' })).toBeVisible();
  await expect(oauth2.getTokenBtn()).toBeEnabled();
}

export async function clearTokenCache(editor: Frame): Promise<void> {
  const oauth2 = buildCommonLocators(editor).oauth2;
  await editor.getByTestId('oauth2-clear-cache-btn').click();
  await expect(oauth2.tokenTitle()).toHaveCount(0);
}

export async function expectErrorToast(editor: Frame, message: RegExp): Promise<void> {
  await expect(editor.getByRole('status').filter({ hasText: message })).toBeVisible();
}

/**
 * Deliver a `vscode://` URI to the running VS Code through "Developer: Open URL" — the same
 * path the OS takes when the browser follows the oauth.usebruno.com redirect.
 */
export async function openVSCodeUri(page: Page, uri: string): Promise<void> {
  await runCommand(page, 'Developer: Open URL');
  // Wait for the command palette (">…") to give way to the "URL to open" prompt. The prompt
  // prefills the last URL it opened; `fill` replaces it.
  const input = page.locator('.quick-input-widget input');
  await expect(input).not.toHaveValue(/^>/);
  await input.fill(uri);
  await page.keyboard.press('Enter');
  await expect(page.locator('.quick-input-widget')).toBeHidden();
}

import { Page, Frame, Locator, expect } from '@playwright/test';

/**
 * Type a value into a SingleLineEditor (CodeMirror) field identified by its
 * data-testid (e.g. "oauth2-field-clientId") or label text as fallback.
 *
 * Waits for focus before typing, presses Tab to blur and commit the onChange,
 * then waits for the focus class to disappear. Includes a 500ms settle time
 * for CodeMirror→Redux propagation (no DOM signal available for this).
 */
export async function fillOAuth2Field(page: Page, editor: Frame, fieldKey: string, value: string) {
  // Try data-testid first, fall back to label text
  let row = editor.locator(`[data-testid="oauth2-field-${fieldKey}"]`);
  if (await row.count() === 0) {
    row = editor.locator(`label:has-text("${fieldKey}")`).locator('..');
  }

  const cmEditor = row.locator('.CodeMirror');
  await expect(cmEditor).toBeVisible({ timeout: 5_000 });
  await cmEditor.click();
  await expect(row.locator('.CodeMirror-focused')).toBeVisible({ timeout: 2_000 });

  // Clear existing content: triple-click to select all (works reliably in CodeMirror)
  await cmEditor.click({ clickCount: 3 });
  await page.keyboard.press('Backspace');

  // Type new value
  await page.keyboard.type(value, { delay: 15 });

  // Blur by pressing Tab — triggers CodeMirror onChange
  await page.keyboard.press('Tab');
  await expect(row.locator('.CodeMirror-focused')).not.toBeVisible({ timeout: 2_000 });

  // Allow Redux to process the onChange dispatch
  await page.waitForTimeout(500);
}

/**
 * Click a dropdown trigger (a selector string or a Locator) and pick an item by text.
 */
export async function selectDropdownItem(editor: Frame, trigger: string | Locator, itemText: string) {
  await (typeof trigger === 'string' ? editor.locator(trigger) : trigger).click();
  const item = editor.locator('.dropdown-item').filter({ hasText: itemText });
  await expect(item).toBeVisible({ timeout: 5_000 });
  await item.click();
  await expect(item).not.toBeVisible({ timeout: 2_000 });
}

/**
 * Re-acquire the editor frame (VS Code may detach/recreate webview frames).
 * Falls back to the provided frame if no active editor is found.
 */
export async function getActiveEditorFrame(page: Page, fallback: Frame): Promise<Frame> {
  for (const frame of page.frames()) {
    if (frame === page.mainFrame()) continue;
    try {
      if (await frame.locator('#send-request').count() > 0) return frame;
    } catch { /* skip detached */ }
  }
  return fallback;
}

/**
 * Fake "system browser" for the browser-based grants (authorization code, implicit).
 *
 * The extension opens the authorize URL with `vscode.env.openExternal`, which e2e can't see.
 * Pointing the `workbench.externalBrowser` setting at this shim makes VS Code hand it the URL
 * instead of launching a real browser; the shim appends each URL to a log file the test reads.
 *
 * VS Code launches the configured browser through the `open` package:
 *  - Linux spawns `<browser> <url>`, so a plain shell script works.
 *  - macOS runs `open -a <browser> <url>`, which only accepts app bundles, so the shim is an
 *    AppleScript applet whose `on open location` handler receives the URL.
 *  - Windows runs PowerShell `Start-Process <browser> -ArgumentList "<url>"`. A `.cmd` shim would
 *    re-parse the URL through cmd.exe, where `&` and `%` are special, so the shim is a tiny
 *    .exe compiled with PowerShell's built-in `Add-Type` that gets the URL as `args[0]`.
 */
import { execFileSync } from 'child_process';
import * as fs from 'fs';
import * as os from 'os';
import * as path from 'path';
import { test as base } from '../../../utils/fixtures';
import { VSCODE_URI_HANDLER_SETTINGS } from './index';

export interface BrowserShim {
  executable: string;
  logFile: string;
}

export function createBrowserShim(dir: string): BrowserShim {
  const logFile = path.join(dir, 'opened-urls.log');
  fs.writeFileSync(logFile, '');

  if (process.platform === 'darwin') {
    const scriptFile = path.join(dir, 'shim.applescript');
    const executable = path.join(dir, 'BrunoBrowserShim.app');
    fs.writeFileSync(
      scriptFile,
      [
        'on open location theURL',
        `  do shell script "printf '%s\\\\n' " & quoted form of theURL & " >> " & quoted form of "${logFile}"`,
        'end open location'
      ].join('\n')
    );
    execFileSync('osacompile', ['-o', executable, scriptFile]);
    return { executable, logFile };
  }

  if (process.platform === 'linux') {
    const executable = path.join(dir, 'browser-shim.sh');
    fs.writeFileSync(executable, `#!/bin/sh\nprintf '%s\\n' "$1" >> '${logFile}'\n`, { mode: 0o755 });
    return { executable, logFile };
  }

  if (process.platform === 'win32') {
    const sourceFile = path.join(dir, 'BrunoBrowserShim.cs');
    const executable = path.join(dir, 'BrunoBrowserShim.exe');
    const csString = (value: string) => `@"${value.replace(/"/g, '""')}"`;
    const psString = (value: string) => `'${value.replace(/'/g, "''")}'`;
    fs.writeFileSync(
      sourceFile,
      [
        'public static class BrunoBrowserShim {',
        '  public static void Main(string[] args) {',
        `    if (args.Length > 0) System.IO.File.AppendAllText(${csString(logFile)}, args[0] + "\\n");`,
        '  }',
        '}'
      ].join('\n')
    );
    execFileSync('powershell.exe', [
      '-NoProfile',
      '-NonInteractive',
      '-Command',
      `Add-Type -Path ${psString(sourceFile)} -OutputAssembly ${psString(executable)} -OutputType WindowsApplication`
    ]);
    return { executable, logFile };
  }

  throw new Error(`Browser shim is not supported on ${process.platform}`);
}

export function clearOpenedUrls(shim: BrowserShim): void {
  fs.writeFileSync(shim.logFile, '');
}

export async function waitForOpenedUrl(shim: BrowserShim, timeoutMs = 15_000): Promise<URL> {
  const deadline = Date.now() + timeoutMs;
  while (Date.now() < deadline) {
    const lines = fs.readFileSync(shim.logFile, 'utf8').split(/\r?\n/).filter(Boolean);
    if (lines.length) {
      return new URL(lines[lines.length - 1]);
    }
    await new Promise((r) => setTimeout(r, 250));
  }
  throw new Error(`No URL was opened in the system browser within ${timeoutMs}ms`);
}

/**
 * `test` for the browser-based grants: each test gets a fresh shim, wired into VS Code's
 * settings together with the URI-handler auto-confirm.
 */
export const test = base.extend<{ browserShim: BrowserShim }>({
  browserShim: async ({}, use) => {
    const dir = fs.mkdtempSync(path.join(os.tmpdir(), 'bruno-browser-shim-'));
    await use(createBrowserShim(dir));
    fs.rmSync(dir, { recursive: true, force: true });
  },
  vscodeSettings: async ({ browserShim }, use) => {
    await use({ 'workbench.externalBrowser': browserShim.executable, ...VSCODE_URI_HANDLER_SETTINGS });
  }
});

/**
 * OAuth2 Implicit against a real Keycloak server.
 *
 * Needs Keycloak on :8180; it is started with docker compose if needed, and the test skips if that fails.
 * The login goes through a fake system browser (see keycloak/browser-shim.ts): the test reads the
 * authorize URL the extension opened, logs in to Keycloak over HTTP, then hands the callback back
 * to VS Code as a `vscode://` URI.
 *
 * One VS Code session, one request; each scenario is a step and starts from an empty token cache.
 */
import { expect } from '../../utils/fixtures';
import { openBrunoSidebar, sendRequest } from '../../utils/page/actions';
import { getActiveEditorFrame } from '../../utils/page/oauth2-actions';
import { buildCommonLocators } from '../../utils/page/locators';
import {
  KEYCLOAK,
  KEYCLOAK_DOWN_REASON,
  KEYCLOAK_START_TIMEOUT,
  BRUNO_CALLBACK_URL,
  ensureKeycloakUp,
  loginToKeycloak,
  toVSCodeCallbackUri
} from './keycloak';
import { test, clearOpenedUrls, waitForOpenedUrl } from './keycloak/browser-shim';
import {
  setupOAuth2Request,
  fillField,
  clickGetAccessToken,
  expectAccessToken,
  clearTokenCache,
  expectErrorToast,
  openVSCodeUri
} from './keycloak-actions';

test.describe('OAuth2 with Keycloak: Implicit', () => {
  test.beforeAll(async () => {
    test.setTimeout(KEYCLOAK_START_TIMEOUT);
    test.skip(!(await ensureKeycloakUp()), KEYCLOAK_DOWN_REASON);
  });

  test('log in through the system browser', async ({ page, tmpDir, browserShim }) => {
    const sidebar = await openBrunoSidebar(page);
    const editor = await setupOAuth2Request(page, sidebar, tmpDir, 'KC Implicit', 'Implicit', KEYCLOAK.userInfoUrl);
    const oauth2 = buildCommonLocators(editor).oauth2;
    const { clientId } = KEYCLOAK.clients.implicit;

    await fillField(page, editor, 'Authorization URL', KEYCLOAK.authorizationUrl);
    await fillField(page, editor, 'Client ID', clientId);
    await fillField(page, editor, 'Scope', KEYCLOAK.scope);

    // Click "Get Access Token" and return the authorize URL the extension opened.
    const startAuthorization = async () => {
      clearOpenedUrls(browserShim);
      await clickGetAccessToken(editor);
      return waitForOpenedUrl(browserShim);
    };

    await test.step('receive the token in the fragment and call a protected resource', async () => {
      const authorizeUrl = await startAuthorization();
      expect(authorizeUrl.searchParams.get('response_type')).toBe('token');
      expect(authorizeUrl.searchParams.get('client_id')).toBe(clientId);
      expect(authorizeUrl.searchParams.get('redirect_uri')).toBe(BRUNO_CALLBACK_URL);
      expect(authorizeUrl.searchParams.get('state')).toMatch(/^[0-9a-f]{32}$/);

      const redirect = await loginToKeycloak(authorizeUrl.toString());
      expect(new URLSearchParams(redirect.hash.slice(1)).get('access_token')).toBeTruthy();
      await openVSCodeUri(page, toVSCodeCallbackUri(redirect));

      await expectAccessToken(editor);
      await sendRequest(await getActiveEditorFrame(page, editor), 200);
    });

    await test.step('configured state is sent as-is', async () => {
      await clearTokenCache(editor);
      await fillField(page, editor, 'State', 'my-fixed-state');

      const authorizeUrl = await startAuthorization();
      expect(authorizeUrl.searchParams.get('state')).toBe('my-fixed-state');

      const redirect = await loginToKeycloak(authorizeUrl.toString());
      expect(new URLSearchParams(redirect.hash.slice(1)).get('state')).toBe('my-fixed-state');
      await openVSCodeUri(page, toVSCodeCallbackUri(redirect));
      await expectAccessToken(editor);

      await fillField(page, editor, 'State', '');
    });

    await test.step('state mismatch on the callback is rejected', async () => {
      await clearTokenCache(editor);

      const authorizeUrl = await startAuthorization();
      const redirect = await loginToKeycloak(authorizeUrl.toString());
      await openVSCodeUri(page, toVSCodeCallbackUri(redirect, { state: 'forged-state' }));

      await expectErrorToast(editor, /state mismatch/i);
      await expect(oauth2.getTokenBtn()).toBeEnabled();
      await expect(oauth2.tokenTitle()).toHaveCount(0);
    });
  });
});

import { useMemo, useState, useEffect } from 'react';
import { useDispatch } from 'react-redux';
import toast from 'react-hot-toast';
import { cloneDeep, find } from 'lodash';
import { IconX } from '@tabler/icons';
import { interpolate } from '@usebruno/common';
import { fetchOauth2Credentials, clearOauth2Cache, refreshOauth2Credentials, cancelOauth2AuthorizationRequest } from 'providers/ReduxStore/slices/collections/actions';
import { getAllVariables } from 'utils/collections/index';
import Button from 'ui/Button';
import type { AppCollection, AppItem, OAuth2CredentialEntry } from '@bruno-types';

interface Oauth2ActionButtonsProps {
  item: AppItem;
  request: Record<string, unknown>;
  collection: AppCollection;
  url: string;
  credentialsId: string;
}

const Oauth2ActionButtons = ({
  item,
  request,
  collection,
  url: accessTokenUrl,
  credentialsId
}: Oauth2ActionButtonsProps) => {
  const collectionUid = collection.uid;

  const dispatch = useDispatch();
  const [fetchingToken, toggleFetchingToken] = useState(false);
  const [refreshingToken, toggleRefreshingToken] = useState(false);
  const oauth2Config = (request as any)?.auth?.oauth2 || {};
  const isBrowserFlow = oauth2Config.grantType === 'authorization_code' || oauth2Config.grantType === 'implicit';
  const showCancelButton = fetchingToken && isBrowserFlow;

  const allVariables = useMemo(() => getAllVariables(collection, item), [collection, item]);

  const interpolatedAccessTokenUrl = useMemo(() => {
    return (interpolate as (str: string, vars: Record<string, unknown>) => string)(accessTokenUrl, allVariables);
  }, [accessTokenUrl, allVariables]);

  const credentialsData = find(
    collection?.oauth2Credentials as OAuth2CredentialEntry[] | undefined,
    (creds) => creds?.url === interpolatedAccessTokenUrl && creds?.collectionUid === collectionUid && creds?.credentialsId === credentialsId
  );
  const creds = (credentialsData?.credentials || {}) as Record<string, unknown>;

  const handleFetchOauth2Credentials = async () => {
    const requestCopy = cloneDeep(request) as Record<string, unknown>;
    const auth = requestCopy.auth as { oauth2?: unknown } | undefined;
    requestCopy.oauth2 = auth?.oauth2;
    requestCopy.headers = {};
    // Attach all resolved variables so the backend can interpolate OAuth2 config fields
    requestCopy.mergedVariables = allVariables;
    toggleFetchingToken(true);
    try {
      const result = await (dispatch(fetchOauth2Credentials({
        itemUid: item.uid,
        request: requestCopy,
        collection
      })) as unknown as Promise<Record<string, unknown>>);

      if (!result || !result.access_token) {
        const errorMessage = (result?.error as string) || 'No access token received from authorization server';
        console.error(errorMessage);
        toast.error(errorMessage);
        return;
      }

      toast.success('Token fetched successfully!');
    } catch (error: unknown) {
      const err = error as { message?: string };
      console.error('could not fetch the token!');
      console.error(error);
      // Don't show error toast for user cancellation
      if (err?.message && err.message.includes('cancelled by user')) {
        return;
      }
      toast.error(err?.message || 'An error occurred while fetching token!');
    } finally {
      toggleFetchingToken(false);
    }
  };

  const handleRefreshAccessToken = async () => {
    const requestCopy = cloneDeep(request) as Record<string, unknown>;
    const auth = requestCopy.auth as { oauth2?: unknown } | undefined;
    requestCopy.oauth2 = auth?.oauth2;
    requestCopy.headers = {};
    // Attach all resolved variables so the backend can interpolate OAuth2 config fields
    requestCopy.mergedVariables = allVariables;
    toggleRefreshingToken(true);
    try {
      const result = await (dispatch(refreshOauth2Credentials({
        itemUid: item.uid,
        request: requestCopy,
        collection
      })) as unknown as Promise<Record<string, unknown>>);

      toggleRefreshingToken(false);

      if (!result || !result.access_token) {
        const errorMessage = (result?.error as string) || 'No access token received from authorization server';
        console.error(errorMessage);
        toast.error(errorMessage);
        return;
      }

      toast.success('Token refreshed successfully!');
    } catch (error: unknown) {
      const err = error as { message?: string };
      console.error(error);
      toggleRefreshingToken(false);
      // Don't show error toast for user cancellation
      if (err?.message && err.message.includes('cancelled by user')) {
        return;
      }
      toast.error(err?.message || 'An error occurred while refreshing token!');
    }
  };

  const handleClearCache = () => {
    (dispatch(clearOauth2Cache({ collectionUid, url: interpolatedAccessTokenUrl, credentialsId })) as unknown as Promise<void>)
      .then(() => {
        toast.success('Cleared cache successfully');
      })
      .catch((err: { message: string }) => {
        toast.error(err.message);
      });
  };

  const handleCancelAuthorization = async () => {
    try {
      await (dispatch(cancelOauth2AuthorizationRequest()) as unknown as Promise<{ success?: boolean; cancelled?: boolean }>);
      toast.error('Authorization cancelled');
      toggleFetchingToken(false);
    } catch (err) {
      console.error('Error cancelling authorization:', err);
      toast.error('Failed to cancel authorization');
    }
  };

  return (
    <div className="flex flex-row gap-2 mt-4">
      <Button
        size="sm"
        color="secondary"
        onClick={handleFetchOauth2Credentials}
        disabled={fetchingToken || refreshingToken}
        loading={fetchingToken}
        data-testid="oauth2-get-token-btn"
      >
        Get Access Token
      </Button>
      {creds?.refresh_token
        ? (
            <Button
              size="sm"
              color="secondary"
              onClick={handleRefreshAccessToken}
              disabled={fetchingToken || refreshingToken}
              loading={refreshingToken}
              data-testid="oauth2-refresh-token-btn"
            >
              Refresh Token
            </Button>
          )
        : null}
      {showCancelButton
        ? (
            <Button
              size="sm"
              color="secondary"
              onClick={handleCancelAuthorization}
              icon={<IconX size={16} />}
              iconPosition="left"
              data-testid="oauth2-cancel-auth-btn"
            >
              Cancel Authorization
            </Button>
          ) : null}
      <Button
        size="sm"
        color="secondary"
        variant="ghost"
        onClick={handleClearCache}
        data-testid="oauth2-clear-cache-btn"
      >
        Clear Cache
      </Button>
    </div>
  );
};

export default Oauth2ActionButtons;

/**
 * OAuth2 authorization using system browser.
 * Opens the authorization URL in the user's default browser and listens
 * for the callback via VS Code's URI handler.
 *
 * Supports both authorization code flow (code in query params)
 * and implicit flow (token in URL fragment).
 *
 * For implicit flow, since URI handlers don't receive fragments,
 * we use a local HTTP server to capture the redirect.
 */

import * as vscode from 'vscode';
import * as http from 'http';
import type { OAuthAdditionalParameter } from '@bruno-types/common/auth';

const AUTHORIZATION_TIMEOUT_MS = 5 * 60 * 1000; // 5 minutes

// --- Module-level state for browser auth tracking ---

let pendingAuthResolve: ((value: AuthorizationResult) => void) | null = null;
let pendingAuthReject: ((reason: Error) => void) | null = null;
let expectedState: string | null = null;
let authTimeoutHandle: ReturnType<typeof setTimeout> | null = null;
let localServer: http.Server | null = null;

export function isAuthorizationInProgress(): boolean {
  return pendingAuthResolve !== null;
}

export function cancelAuthorization(): void {
  settleReject(new Error('Authorization was cancelled by user'));
}

function cleanup(): void {
  expectedState = null;
  pendingAuthResolve = null;
  pendingAuthReject = null;
  if (authTimeoutHandle) {
    clearTimeout(authTimeoutHandle);
    authTimeoutHandle = null;
  }
  if (localServer) {
    localServer.close();
    localServer = null;
  }
}

// Capture the pending callback before cleanup() clears it, then settle.
function settleResolve(result: AuthorizationResult): void {
  const resolve = pendingAuthResolve;
  cleanup();
  resolve?.(result);
}

function settleReject(error: Error): void {
  const reject = pendingAuthReject;
  cleanup();
  reject?.(error);
}

// --- URI handler for authorization code callback ---

export function createOAuth2UriHandler(): vscode.UriHandler {
  return {
    handleUri(uri: vscode.Uri): void {
      if (!pendingAuthResolve) return;

      const params = new URLSearchParams(uri.query);
      const error = params.get('error');
      if (error) {
        const desc = params.get('error_description') || error;
        settleReject(new Error(`OAuth2 authorization error: ${desc}`));
        return;
      }

      // Validate state to protect against CSRF / authorization code injection.
      const returnedState = params.get('state') || new URLSearchParams(uri.fragment).get('state');
      if (!expectedState || returnedState !== expectedState) {
        settleReject(new Error('OAuth2 state mismatch: the returned state does not match the issued state.'));
        return;
      }

      const code = params.get('code');
      if (code) {
        settleResolve({ authorizationCode: code, callbackUri: uri.toString(true) });
        return;
      }

      // For implicit flow via URI handler (unlikely since fragments aren't forwarded)
      const accessToken = params.get('access_token');
      if (accessToken) {
        settleResolve({
          implicitTokens: {
            access_token: accessToken,
            token_type: params.get('token_type') || 'Bearer',
            expires_in: params.get('expires_in') || undefined,
            scope: params.get('scope') || undefined,
            state: params.get('state') || undefined
          }
        });
      }
    }
  };
}

// --- Types ---

export interface AuthorizationResult {
  authorizationCode?: string;
  authorizeUrl?: string;
  callbackUri?: string;
  implicitTokens?: {
    access_token: string;
    token_type: string;
    expires_in?: string;
    scope?: string;
    state?: string;
  };
}

interface AuthorizationCodeOptions {
  authorizationUrl: string;
  callbackUrl: string;
  clientId: string;
  scope?: string;
  state?: string;
  pkce?: boolean;
  codeChallenge?: string;
  additionalParameters?: OAuthAdditionalParameter[];
}

interface ImplicitFlowOptions {
  authorizationUrl: string;
  callbackUrl: string;
  clientId: string;
  scope?: string;
  state?: string;
  additionalParameters?: OAuthAdditionalParameter[];
}

export async function getOAuth2AuthorizationCode(options: AuthorizationCodeOptions): Promise<AuthorizationResult> {
  if (isAuthorizationInProgress()) {
    cancelAuthorization();
  }

  const { authorizationUrl, callbackUrl, clientId, scope, state, pkce, codeChallenge, additionalParameters } = options;

  const url = new URL(authorizationUrl);
  url.searchParams.append('response_type', 'code');
  url.searchParams.append('client_id', clientId);

  if (callbackUrl) {
    url.searchParams.append('redirect_uri', callbackUrl);
  }
  if (scope) {
    url.searchParams.append('scope', scope);
  }
  if (state) {
    url.searchParams.append('state', state);
  }
  if (pkce && codeChallenge) {
    url.searchParams.append('code_challenge', codeChallenge);
    url.searchParams.append('code_challenge_method', 'S256');
  }

  // Apply additional authorization parameters (queryparams only for auth URL)
  if (additionalParameters?.length) {
    additionalParameters.forEach((param) => {
      if (param.enabled && param.name && param.sendIn === 'queryparams') {
        url.searchParams.append(param.name, param.value || '');
      }
    });
  }

  return openBrowserAndWaitForCallback(url.toString(), state);
}

export async function getOAuth2ImplicitToken(options: ImplicitFlowOptions): Promise<AuthorizationResult> {
  if (isAuthorizationInProgress()) {
    cancelAuthorization();
  }

  const { authorizationUrl, callbackUrl, clientId, scope, state, additionalParameters } = options;

  const url = new URL(authorizationUrl);
  url.searchParams.append('response_type', 'token');
  url.searchParams.append('client_id', clientId);

  if (callbackUrl) {
    url.searchParams.append('redirect_uri', callbackUrl);
  }
  if (scope) {
    url.searchParams.append('scope', scope);
  }
  if (state) {
    url.searchParams.append('state', state);
  }

  if (additionalParameters?.length) {
    additionalParameters.forEach((param) => {
      if (param.enabled && param.name && param.sendIn === 'queryparams') {
        url.searchParams.append(param.name, param.value || '');
      }
    });
  }

  return openBrowserAndWaitForCallback(url.toString(), state);
}

async function openBrowserAndWaitForCallback(authorizeUrl: string, state?: string): Promise<AuthorizationResult> {
  return new Promise<AuthorizationResult>((resolve, reject) => {
    pendingAuthResolve = (result) => resolve({ ...result, authorizeUrl });
    pendingAuthReject = reject;
    expectedState = state || null;

    authTimeoutHandle = setTimeout(() => {
      settleReject(new Error('OAuth2 authorization timed out after 5 minutes'));
    }, AUTHORIZATION_TIMEOUT_MS);

    vscode.env.openExternal(vscode.Uri.parse(authorizeUrl)).then((opened) => {
      if (!opened) {
        settleReject(new Error('Failed to open authorization URL in system browser'));
      }
    });
  });
}

